+// PeekWithExpiry returns the key value (or undefined if not found), along with
+// the time the entry expires; without updating the "recently used"-ness of the key.
+// For a missing key or an expired entry it returns the zero value, the zero time and false.
+func (c *LRU[K, V]) PeekWithExpiry(key K) (value V, expiresAt time.Time, ok bool) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	var ent *internal.Entry[K, V]
+	if ent, ok = c.items[key]; ok {
+		// Expired item check
+		if !c.cleanupStopped && time.Now().After(ent.ExpiresAt) {
+			return value, time.Time{}, false
+		}
+		return ent.Value, ent.ExpiresAt, true
+	}
+	return
+}
