+func TestLRUPeekWithExpiry(t *testing.T) {
+	lc := NewLRU[string, string](10, nil, time.Millisecond*5)
+
+	// Valid, non-expired entry
+	lc.Add("key1", "val1")
+	v, expiresAt, ok := lc.PeekWithExpiry("key1")
+	if v != "val1" {
+		t.Fatalf("value differs from expected: got %q", v)
+	}
+	if !ok {
+		t.Fatalf("should be true")
+	}
+	if expiresAt.IsZero() {
+		t.Fatalf("expiresAt should not be zero")
+	}
+
+	// Missing key
+	v, expiresAt, ok = lc.PeekWithExpiry("nonexistent")
+	if v != "" {
+		t.Fatalf("value should be empty: got %q", v)
+	}
+	if !expiresAt.IsZero() {
+		t.Fatalf("expiresAt should be zero")
+	}
+	if ok {
+		t.Fatalf("should be false")
+	}
+
+	// Wait for expiration
+	time.Sleep(time.Millisecond * 100)
+	v, expiresAt, ok = lc.PeekWithExpiry("key1")
+	if v != "" {
+		t.Fatalf("value should be empty after expiry: got %q", v)
+	}
+	if !expiresAt.IsZero() {
+		t.Fatalf("expiresAt should be zero after expiry")
+	}
+	if ok {
+		t.Fatalf("should be false after expiry")
